using System.Collections.Generic;using FallenForest.Core;using UnityEngine;namespace FallenForest.Documents{public sealed class DocumentSpawner:MonoBehaviour{[SerializeField]private DocumentPickup documentPrefab;[SerializeField]private List<DocumentSpawnPoint> spawnPoints=new();[SerializeField]private int count=10;[SerializeField]private float minimumSpacing=28f,minimumFromStart=34f;[SerializeField]private Transform startPoint;[SerializeField]private int seedOverride;private readonly List<Vector3> chosenPositions=new();private void Start()=>SpawnDocuments();public void SpawnDocuments(){if(documentPrefab==null||spawnPoints.Count==0)return;int seed=seedOverride!=0?seedOverride:SaveSystem.RunSeed;System.Random rng=new(seed^0x5F3759DF);List<DocumentSpawnPoint> pool=new();foreach(DocumentSpawnPoint p in spawnPoints){if(p==null||!p.EnabledForSpawn)continue;if(startPoint!=null&&Vector3.Distance(Flat(p.transform.position),Flat(startPoint.position))<minimumFromStart)continue;pool.Add(p);}for(int i=pool.Count-1;i>0;i--){int j=rng.Next(i+1);(pool[i],pool[j])=(pool[j],pool[i]);}chosenPositions.Clear();int selected=0;for(int i=0;i<pool.Count&&selected<count;i++){DocumentSpawnPoint point=pool[i];bool tooClose=false;foreach(Vector3 c in chosenPositions)if(Vector3.Distance(Flat(c),Flat(point.transform.position))<minimumSpacing){tooClose=true;break;}if(tooClose)continue;chosenPositions.Add(point.transform.position);int slot=selected++;if(SaveSystem.IsDocumentCollected(slot))continue;DocumentPickup instance=Instantiate(documentPrefab,point.transform.position,point.transform.rotation,transform);instance.name=$"Document_{slot+1:00}";instance.Configure(slot);}if(selected<count)Debug.LogWarning($"Fallen Forest: only {selected}/{count} valid document positions.");}private static Vector3 Flat(Vector3 v)=>new(v.x,0,v.z);}}
